test('regression: normalizeProviderPayload still returns correct current weather shape after Day 23 pull', () => {
  const normalized = normalizeProviderPayload(minimalProviderPayload);

  assert.equal(normalized.current.temperature_c, 29);
  assert.equal(normalized.current.feels_like_c, 32);
  assert.equal(normalized.current.humidity_percent, 68);
  assert.equal(normalized.current.condition, 'sunny');
  assert.equal(normalized.current.conditionLabel, 'Clear Sky');
  assert.ok(typeof normalized.current.rain_probability_percent === 'number');
  assert.ok(Array.isArray(normalized.hourly));
  assert.ok(Array.isArray(normalized.daily));
});

test('regression: travel-risk assessDestinationWeather returns stable shape after Day 23 pull', () => {
  const weather = normalizeProviderPayload(minimalProviderPayload).current;
  const result = assessDestinationWeather(weather, { destinationLabel: 'Regression City' });

  assert.ok(typeof result.score === 'number', 'score must be a number');
  assert.ok(['low', 'moderate', 'high'].includes(result.riskLevel), 'riskLevel must be low/moderate/high');
  assert.ok(typeof result.summary === 'string' && result.summary.length > 0, 'summary must be non-empty');
  assert.ok(Array.isArray(result.factors) && result.factors.length > 0, 'factors must be a non-empty array');
  assert.ok(result.summary.includes('Regression City'), 'summary must include destination label');
});

test('regression: riskLevelForScore boundaries are stable (low < 40, moderate 40-69, high ≥ 70)', () => {
  const w = (overrides) => ({ temperature_c: 20, feels_like_c: 20, rain_probability_percent: 0,
    wind_speed_kmh: 10, uv_index: 3, visibility_km: 10, condition: 'sunny', conditionLabel: 'Clear Sky', ...overrides });

  const low    = assessDestinationWeather(w({}));
  const moderate = assessDestinationWeather(w({ temperature_c: 33, feels_like_c: 36, rain_probability_percent: 60 }));
  const high   = assessDestinationWeather(w({ condition: 'stormy', temperature_c: 40, feels_like_c: 42,
    rain_probability_percent: 95, wind_speed_kmh: 55, uv_index: 9, visibility_km: 2 }));

  assert.equal(low.riskLevel,    'low');
  assert.equal(moderate.riskLevel, 'moderate');
  assert.equal(high.riskLevel,   'high');
});

